use crate::const_shared::{self as shared, Decls};
use crate::const_values::Big;
use crate::{Corpus, Rule, SourceFile, SourceSet};
use regex::Regex;
use std::collections::{BTreeMap, BTreeSet};
use std::sync::OnceLock;

pub struct ConstVsOwnIsland;
const INPUTS: &[SourceSet] =
    &[
        SourceSet::tree("const-vs-own-island-rust", &["sdk/lib/rust"], &["rs"], &[])
            .with_pruning(&["target", ".responses"])
            .with_inputs(),
    ];

fn own_mark() -> &'static str {
    "@generated by tools/rustconv/gen_driver_types.sh"
}
fn island_const_re() -> &'static Regex {
    static R: OnceLock<Regex> = OnceLock::new();
    R.get_or_init(|| crate::regexes::cached(
        r"^\s*pub const ([A-Za-z_][A-Za-z0-9_]*)\s*:\s*([^=]+?)\s*=\s*(-?(?:0[xX][0-9A-Fa-f_]+|\d[\d_]*))\s*;"
    ).unwrap())
}
fn ignored_re() -> &'static Regex {
    static R: OnceLock<Regex> = OnceLock::new();
    R.get_or_init(|| crate::regexes::cached(r"(/target/|/\.responses/)").unwrap())
}
fn crate_of(rel: &str) -> &str {
    let parts = rel.split('/').collect::<Vec<_>>();
    if parts.len() > 3 && parts[..3] == ["sdk", "lib", "rust"] {
        parts[3]
    } else {
        rel
    }
}

/// Exact `own_island_values()` behavior: index only the literal symbol emitted by
/// gen_driver_types.sh. Unlike `island_values()`, Python does not add enum member
/// aliases here, so `_TYPE_Member` does not also populate `Member`.
fn own_values<'a>(files: impl Iterator<Item = &'a SourceFile>) -> BTreeMap<String, BTreeSet<Big>> {
    let mut out = BTreeMap::<String, BTreeSet<Big>>::new();
    for f in files {
        let rel = f.path.to_string_lossy();
        if ignored_re().is_match(&rel)
            || !f
                .text
                .chars()
                .take(800)
                .collect::<String>()
                .contains(own_mark())
        {
            continue;
        }
        let crate_name = crate_of(&rel);
        for line in f.text.lines() {
            let Some(m) = island_const_re().captures(line) else {
                continue;
            };
            let (Some(name), Some(raw)) = (m.get(1), m.get(3)) else {
                continue;
            };
            let Some(value) = Big::parse(raw.as_str()) else {
                continue;
            };
            out.entry(format!("{crate_name}\0{}", name.as_str()))
                .or_default()
                .insert(value);
        }
    }
    out
}

fn shadows(decls: &Decls, own: &BTreeMap<String, BTreeSet<Big>>) -> Vec<(String, String, Big)> {
    let mut out = BTreeSet::new();
    for (name, sites) in decls {
        for site in sites {
            let key = format!("{}\0{name}", crate_of(&site.path));
            let Some(values) = own.get(&key) else {
                continue;
            };
            // Python compares both 32- and 64-bit masked values with arbitrary precision.
            if !values
                .iter()
                .any(|v| site.value.same_bits(v, 32) || site.value.same_bits(v, 64))
            {
                out.insert((name.clone(), site.path.clone(), site.value.clone()));
            }
        }
    }
    out.into_iter().collect()
}

impl Rule for ConstVsOwnIsland {
    fn name(&self) -> &'static str {
        "scan_const_vs_own_island"
    }
    fn source_sets(&self) -> &'static [SourceSet] {
        INPUTS
    }
    fn run(&self, corpus: &Corpus) -> Result<Vec<String>, String> {
        let declarations = shared::declarations(corpus, "const-vs-own-island-rust", true);
        let islands = own_values(corpus.sources("const-vs-own-island-rust"));
        Ok(shadows(&declarations, &islands)
            .into_iter()
            .map(|(name, path, value)| {
                format!(
                    "{path}: {name} = {} [VS_OWN_ISLAND]",
                    shared::render(&value)
                )
            })
            .collect())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    fn v(s: &str) -> Big {
        Big::parse(s).unwrap()
    }
    #[test]
    fn own_island_literal_names_are_not_expanded_to_enum_members() {
        let f = SourceFile::new("sdk/lib/rust/cdrom-rust/src/types.rs".into(),
            "// @generated by tools/rustconv/gen_driver_types.sh\npub const _FEATURE_NUMBER_FeatureDvdRead: _FEATURE_NUMBER = 31;\n".into());
        let values = own_values([&f].into_iter());
        assert_eq!(
            values["cdrom-rust\0_FEATURE_NUMBER_FeatureDvdRead"],
            [v("31")].into()
        );
        assert!(!values.contains_key("cdrom-rust\0FeatureDvdRead"));
        let declarations = Decls::from([(
            "FeatureDvdRead".into(),
            vec![shared::Site {
                path: "sdk/lib/rust/cdrom-rust/src/file.rs".into(),
                value: v("18"),
                arch: "common".into(),
            }],
        )]);
        // The Python implementation likewise looks up only the literal generated name.
        assert!(shadows(&declarations, &values).is_empty());
    }
    #[test]
    fn same_symbol_uses_python_32_and_64_bit_mask_comparison() {
        let f = SourceFile::new(
            "sdk/lib/rust/foo-rust/src/types.rs".into(),
            "// @generated by tools/rustconv/gen_driver_types.sh\npub const VALUE: u32 = -1;\n"
                .into(),
        );
        let values = own_values([&f].into_iter());
        for (n, want) in [
            ("4294967295", false),
            ("18446744073709551615", false),
            ("7", true),
        ] {
            let d = Decls::from([(
                "VALUE".into(),
                vec![shared::Site {
                    path: "sdk/lib/rust/foo-rust/src/a.rs".into(),
                    value: v(n),
                    arch: "common".into(),
                }],
            )]);
            assert_eq!(!shadows(&d, &values).is_empty(), want, "{n}");
        }
    }
    #[test]
    fn generated_marker_window_and_nolint_declaration_path_remain_in_shared_collector() {
        let generated = SourceFile::new(
            "sdk/lib/rust/foo-rust/src/types.rs".into(),
            format!("// {}\npub const VALUE: u32 = 8;", own_mark()),
        );
        assert!(own_values([&generated].into_iter()).contains_key("foo-rust\0VALUE"));
        let d = Decls::from([(
            "VALUE".into(),
            vec![shared::Site {
                path: "sdk/lib/rust/foo-rust/src/a.rs".into(),
                value: v("9"),
                arch: "common".into(),
            }],
        )]);
        assert_eq!(shadows(&d, &own_values([&generated].into_iter())).len(), 1);
    }
}
